package dev.zomboid.mts;import java.util.*;import minecrafttransportsimulator.entities.instances.*;import minecrafttransportsimulator.baseclasses.EntityInteractResult;
public class PickerChecks {static int n;static void check(boolean b){n++;if(!b)throw new AssertionError("picker case "+n);}public static class Definition {public Object action;}public static class Box {public Definition definition;public Set<String> collisionTypes=Set.of("CLICK");public Checks.Point pos;public Box(double x,double y,double z){pos=new Checks.Point(x,y,z);}public Object getIntersection(Object a,Object b){return new Hit(pos);}}public static class Hit {public Object position;public Hit(Object p){position=p;}}public static class World {public List<Object> vehicles=new ArrayList<>();public Collection<?> getEntitiesOfType(Class<?> c){return vehicles;}}
 public static void main(String[]args){EntityVehicleF_Physics car=new EntityVehicleF_Physics();PartSeat seat=new PartSeat();seat.vehicleOn=car;World world=new World();world.vehicles.add(car);Checks.Point eye=new Checks.Point(0,0,0),camera=new Checks.Point(0,10,0),end=new Checks.Point(0,-10,0);Box roof=new Box(0,2,0),inside=new Box(0,1,0);car.allCollisionBoxes.add(roof);car.allCollisionBoxes.add(inside);car.boxParts.put(inside,seat);EntityInteractResult original=new EntityInteractResult(car,roof,roof.pos);Object result=VehiclePicker.choose(world,eye,camera,end,original);check(R.get(result,"entity")==seat);check(VehiclePicker.choose(world,eye,camera,end,result)==result);Box door=new Box(0,2,1);door.definition=new Definition();door.definition.action=new Object();EntityInteractResult doorHit=new EntityInteractResult(car,door,door.pos);check(VehiclePicker.choose(world,eye,camera,end,doorHit)==doorHit);inside.pos=new Checks.Point(0,20,0);check(VehiclePicker.choose(world,eye,camera,end,original)==original);inside.pos=new Checks.Point(0,1,0);inside.collisionTypes=Set.of("BLOCK");check(VehiclePicker.choose(world,eye,camera,end,original)==original);System.out.println("Vehicle picker checks: "+n);}}
